import csv,re,glob,json
from collections import defaultdict

def parse_doc(path):
    t=open(path,encoding='utf-8').read().strip(); d={}
    for part in re.split(r'[；;]',t):
        part=part.strip()
        if not part: continue
        m=re.match(r'([^:：\s]+)[:：\s]\s*(.*)',part)
        if m: d[m.group(1)]=m.group(2).strip().rstrip('。')
    m=re.search(r'第(\d+)日至第(\d+)日',d['有效期'])
    return dict(obj=d['对象'],flow=int(d['签发流水']),cat=d['类别'],signer=d['签发人'],
                start=int(m.group(1)),end=int(m.group(2)),station=d['主站'])
docs=[parse_doc(p) for p in glob.glob('inbox/06-02/签署附件/*/*.txt')]
roster={r['对象']:r['授权签发人'] for r in csv.DictReader(open('notes/签发名册_06-02.csv',encoding='utf-8-sig'))}
def pick_station(obj,biz=3):
    cand=[x for x in docs if x['obj']==obj and x['cat']=='正式' and roster.get(obj)==x['signer'] and x['start']<=biz<=x['end']]
    if not cand: return None
    cand.sort(key=lambda x:(x['start'],x['flow']))
    return cand[-1]

# applications 06-03
rows=list(csv.DictReader(open('inbox/06-03/设备申请.csv',encoding='utf-8-sig')))
agg=defaultdict(lambda: defaultdict(list)); prio={}; catg={}
for r in rows:
    agg[r['案号']][r['设备序号']].append(r)
    if r['案号'] in prio: assert prio[r['案号']]==int(r['优先号']),(r['案号'],prio[r['案号']],r['优先号'])
    if r['案号'] in catg: assert catg[r['案号']]==r['服务类别'],(r['案号'],catg[r['案号']],r['服务类别'])
    prio[r['案号']]=int(r['优先号']); catg[r['案号']]=r['服务类别']
def demand(c):
    tot=0
    for dev,rs in agg[c].items():
        rs.sort(key=lambda x:int(x['修订号'])); mx=rs[-1]
        if mx['状态']!='取消': tot+=int(mx['申请席位'])
    return tot
objmap={}
for r in rows: objmap[r['案号']]=None
# object map from release list
rel=list(csv.reader(open('inbox/06-03/第一批放行.csv',encoding='utf-8-sig')))
obj_of={r[0]:r[1] for r in rel if len(r)==2 and r[0].startswith('P')}
release=['P01','P02','P03','P04','P05','P06','P07','P09','P10','P11']
defer=['P08','P12']
voucher={(r['主站'],r['服务类别']):r['凭证'] for r in csv.DictReader(open('input/现场服务/凭证册.csv',encoding='utf-8-sig'))}
cap={}
for r in csv.DictReader(open('input/现场服务/期初容量.csv',encoding='utf-8-sig')):
    if int(r['生效日'])<=3: cap[r['主站']]=cap.get(r['主站'],0)+int(r['增额'])
term={'HZ-A':'7个工作日','HZ-B':'10个工作日','JL-A':'10个工作日','JL-B':'5个工作日','NP-A':'10个工作日','NP-B':'10个工作日','YC-A':'10个工作日','YC-B':'10个工作日','QH-A':'10个工作日','QH-B':'10个工作日','BA-A':'10个工作日','BA-B':'10个工作日'}

info={}
for c in release+defer:
    o=obj_of[c]; d=pick_station(o); st=d['station']
    info[c]=dict(obj=o,station=st,flow=d['flow'],cat=catg[c],demand=demand(c),
                 voucher=voucher[(st,catg[c])],term=term[o],priority=prio[c])
order=sorted(release,key=lambda c:(prio[c],c))
remain=dict(cap); res={}
for c in order:
    need=info[c]['demand']; st=info[c]['station']; have=remain[st]
    if have>=need: res[c]=need; remain[st]=have-need
    else: res[c]=0
    print(f"{c} {info[c]['obj']:5} 优先{prio[c]:>3} 站{st} 类{catg[c]} 需{need} 余前{have} -> 席位{res[c]} 余后{remain[st]}")
for c in release+defer: info[c]['reserved']=res.get(c,None)
print('remain',remain)
print('---deferred---')
for c in defer: print(c,info[c])
json.dump(info,open('notes/R3_附页演算.json','w',encoding='utf-8'),ensure_ascii=False,indent=2)
